182	pub struct CompiledPrompt {
183	    pub user_prompt: String,
184	    pub system_prompt: Option<String>,
185	    /// The code task it was sent from, which fills in its instructions as it
186	    /// is sent (see [`Self::instructions_as_sent`]).
187	    pub code_task: Option<CodeTask>,
188	    /// The images attached to it, to give the harness alongside the prompt,
189	    /// in the order they were attached; never part of the prompt's text.
190	    pub images: Vec<PathBuf>,
191	    /// The model it goes to, as its harness is told it; none for the
192	    /// harness's own.
193	    pub model: Option<String>,
194	}
