196	impl CompiledPrompt {
197	    /// Its instructions as they head its message: `${UNDERSTANDING_FILE}`
198	    /// filled in with `understanding`, the understanding file's path from the
199	    /// project directory, or nothing for a question; then the code task it was
200	    /// sent from, last, so nothing in what that holds is filled in.
201	    pub fn instructions_as_sent(&self, understanding: Option<&str>) -> Option<String> {
202	        let system_prompt = self.system_prompt.as_deref()?;
203	        let filled = system_prompts::fill_understanding(system_prompt, understanding);
204	        Some(match &self.code_task {
205	            Some(code) => {
206	                system_prompts::fill_code_task(&filled, &code.prompt, code.result.as_deref())
207	            }
208	            None => filled,
209	        })
210	    }
211	}
