        );
        system_prompts::save(SendMode::Spec, "${PITON_FLUENCY}", &project_dir).unwrap();
        assert_eq!(instructions(SendMode::Spec, &project_dir).unwrap(), None);
        fs::remove_dir_all(&project_dir).ok();
