    fn prompts_split_into_text_and_references() {
        use super::{Piece, pieces};
        assert_eq!(
            pieces("See @{App-scope.concept} and ${Foo}, not ${1x} or @{a b} or ${"),
            [
                Piece::Text("See "),
                Piece::Reference("@{App-scope.concept}", "App-scope"),
