        cx.run_until_parked();
        let dir = prompt_mode.read_with(cx, |this, _| this.project_dir.clone().unwrap());
        let frame = |cx: &mut TestAppContext| {
            cx.update_window(handle, |_, window, cx| window.render_frame(cx))
                .unwrap();
        };
        frame(cx);

        prompt_mode.update(cx, |this, cx| {
