                this.show_compiled(ix, "Prompt_0".into(), compiled.into(), cx);
            });
        })
        .unwrap();
        cx.wait_for(handle, Duration::from_secs(1), |window, _| {
            window.try_find(("prompt-slices", 0usize)).is_some()
