    async fn prompts_keep_the_model_they_were_sent_to(cx: &mut TestAppContext) {
        use crate::agent::Agent;
        use crate::chat_input::SendMode;
        let dir = std::env::temp_dir().join(format!("suspense-model-anchor-{}", std::process::id()));
