        let id = prompt_mode.update(cx, |this, cx| {
            this.on_ask_tab = true;
            let id = this.start_test_question("Long?", cx);
            this.update_ask(id, |ask| ask.apply(HarnessEvent::TextDelta(long.clone())), cx);
            id
        });
