        frames(handle, cx);
        let pane = bounds_of(handle, "ask-pane-scroll", cx).unwrap();
        let start = bounds_of(handle, ("question", super::ASK_IX - id), cx);
        // The question's box is just above, out of view; its answer's start
        // is at the top.
