            divider(super::ASK_IX - 1, cx),
            "the first conversation isn't marked"
        );
        assert!(
            !divider(super::ASK_IX - 2, cx),
            "a question carrying on is marked"
        );
        assert!(
            divider(super::ASK_IX - 3, cx),
            "the new conversation isn't marked"
        );
