        assert!(prompt_mode.read_with(cx, |this, _| this.task_history.expanded));
        still();
        wheel(cx, -40.);
        assert_eq!(
            built_up(cx),
            40.,
            "a scroll from the previous tasks' bottom didn't stretch"
        );
    }

