                    window,
                    cx,
                )
            })
        })
        .unwrap();
        run_until(cx, &prompt_mode, "the naming", |this| {
            this.tasks
                .first()
                .is_some_and(|task| task.name.as_ref() == "TidyTheQueue")
        });
