    /// Whether the harness is working on a task or a question in any open
    /// project.
    pub fn is_working(&self) -> bool {
        self.working.any()
            || self.asks.iter().any(|ask| ask.task.status.is_active())
            || !self.busy_projects().is_empty()
    }

    /// The prompts queued, oldest first.
