            Self::Sending => format!("Being sent to {to}"),
            Self::Sent => format!("Sent to {to}"),
            Self::MarkedDone => "Marked as done".to_string(),
            // Sent here from the mode it would be sent back to.
            Self::Complete => format!("Complete, sent here from {to}"),
