            })
        })
        .into_any_element()
}

/// A previous task's, or chain's, duration column: right-aligned, as wide
/// for every heading, so the times line up; empty when it can't be told.
fn duration_column(id: (&'static str, usize), took: Option<Took>, cx: &App) -> Div {
    div()
        .flex_none()
        .w(DURATION_COLUMN)
        .flex()
        .justify_end()
        .children(took.map(|took| took_label(id, took, cx)))
}

/// A chain's status as a whole: running while any step is, failed or
/// cancelled if any step was, and otherwise its last step's.
fn chain_status(steps: &[&PromptTask]) -> TaskStatus {
    let statuses = steps.iter().map(|task| task.status);
    if let Some(active) = statuses.clone().find(|status| status.is_active()) {
        return active;
    }
    for ended in [TaskStatus::Failed, TaskStatus::Cancelled] {
        if statuses.clone().any(|status| status == ended) {
            return ended;
        }
    }
    steps
        .last()
        .map_or(TaskStatus::Unrecorded, |task| task.status)
}

/// How strongly a chain's parent row is tinted with the Chain colour, a
/// little more than a single task's heading.
const CHAIN_HINT: f32 = 0.12;

/// How far a chain's steps are set in beneath its parent row.
const CHAIN_INDENT: Pixels = px(14.);

/// How strongly a previous task's heading is tinted with its mode's colour:
/// only a hint of it.
const HISTORY_MODE_HINT: f32 = 0.07;

/// Scrolling past an end of the latest task, `up` into the previous tasks,
/// or of the previous tasks back down to it, sliding one in for the other.
struct ScrollSlide {
    /// Counts the slides, so each springs from its start.
    n: usize,
    up: bool,
    started: Instant,
    /// How far toward the barrier the glow had grown as it crossed over,
    /// fading out as the slide begins; none for a slide it didn't start.
    glow: f32,
    /// How far the stretch had pulled the view as it crossed over, down
    /// for up, the slide starting from there.
    pull: Pixels,
}

/// The time a scroll past an end goes by: the system's, or, in a test that
/// has frozen it, a clock of the test's own that moves only as the test
/// moves it, so a slow machine never turns one gesture into two.
fn scroll_now() -> Instant {
    #[cfg(test)]
    if let Some(now) = TEST_CLOCK.get() {
        return now;
    }
    Instant::now()
}

#[cfg(test)]
thread_local! {
    static TEST_CLOCK: std::cell::Cell<Option<Instant>> = const { std::cell::Cell::new(None) };
}

/// Freezes the time scrolls go by, on this test's thread.
#[cfg(test)]
fn freeze_clock() {
    TEST_CLOCK.set(Some(Instant::now()));
}

/// Moves the frozen time scrolls go by on by `by`.
#[cfg(test)]
fn advance_clock(by: Duration) {
    TEST_CLOCK.set(TEST_CLOCK.get().map(|now| now + by));
}

/// A scroll pushing into the stretch at an end: which way, and how far past
/// it, as of `at`, draining away once the scrolling pauses.
#[derive(Clone, Copy)]
struct ScrollPush {
    up: bool,
    amount: f32,
    at: Instant,
}

impl Default for ScrollPush {
    fn default() -> Self {
        Self {
            up: false,
            amount: 0.,
            at: scroll_now(),
        }
    }
}

impl ScrollPush {
    /// How far it has built up at `now`: all of it while the scroll goes
    /// on, draining only once it has stopped, [`SCROLL_HOLD`] after its last
    /// step, to nothing by [`SCROLL_DRAIN`] after it.
    fn held(&self, now: Instant) -> f32 {
        let since = now.duration_since(self.at);
        if since <= SCROLL_HOLD {
            return self.amount;
        }
        let drained =
            (since - SCROLL_HOLD).as_secs_f32() / (SCROLL_DRAIN - SCROLL_HOLD).as_secs_f32();
        self.amount * (1. - drained).max(0.)
    }

    /// How far the stretch pulls the view past its end at `now`, down while
    /// scrolling up: nearly as far as it built up at first, less the further
    /// it goes, as a rubber band gives, and about [`STRETCH_PULL`] by the
    /// barrier.
    fn pull(&self, now: Instant) -> Pixels {
        let held = self.held(now);
        if held <= 0. {
            return px(0.);
        }
        let pull = (STRETCH_GIVE * held / (STRETCH_GIVE + held)).min(STRETCH_PULL);
        px(if self.up { pull } else { -pull })
    }
}

/// Whether each wheel event over the latest task or the previous tasks is
/// written to standard error with what came of it, for seeing how a
/// platform's scrolling reaches the stretch: set `SUSPENSE_SCROLL_LOG`.
static SCROLL_LOG: std::sync::LazyLock<bool> =
    std::sync::LazyLock::new(|| std::env::var_os("SUSPENSE_SCROLL_LOG").is_some());

/// How far the stretch pulls the view by the barrier, and never more.
const STRETCH_PULL: f32 = 64.;

/// How quickly the stretch stiffens, as a rubber band does: it gives all of
/// a scroll at first, less and less the further it goes, and still gives a
/// little right up to the barrier, reaching [`STRETCH_PULL`] just as the
/// build-up reaches [`SCROLL_BARRIER`].
const STRETCH_GIVE: f32 = STRETCH_PULL * SCROLL_BARRIER / (SCROLL_BARRIER - STRETCH_PULL);

/// How far a scroll must push past an end to cross over.
const SCROLL_BARRIER: f32 = 768.;

/// How long a scroll's steps may be apart and it still goes on: until then,
/// nothing it built up against an end drains.
const SCROLL_HOLD: Duration = Duration::from_millis(200);

/// How long after a scroll's last step what it built up against an end has
/// drained away.
const SCROLL_DRAIN: Duration = Duration::from_millis(500);

/// How quickly the glow fades as the view crosses over.
const GLOW_FADE: Duration = Duration::from_millis(150);

/// How long the wheel must rest before a scroll counts as a new one, after a
/// slide or a fling, which then pulls into the stretch at an end again:
/// barely a pause. A trackpad touch starting is a new scroll at once.
const SCROLL_REST: Duration = Duration::from_millis(80);

/// The gap an item dragged over the item at `ix`, whose bounds are
/// `bounds`, would be dropped into, the pointer at `at`: the gap before it
/// over its first half, the one after it over its second, halves taken
/// `along` the way the items run. None while the pointer is off it.
fn drag_gap(ix: usize, bounds: Bounds<Pixels>, at: Point<Pixels>, vertical: bool) -> Option<usize> {
    if !bounds.contains(&at) {
        return None;
    }
    let after = if vertical {
        at.y > bounds.center().y
    } else {
        at.x > bounds.center().x
    };
    Some(ix + after as usize)
}

/// The item a drag from `from` lands at, dropped in `gap`, and whether that
/// moves it at all: the gaps either side of it are where it already is.
fn gap_target(from: usize, gap: usize) -> Option<usize> {
    (gap != from && gap != from + 1).then(|| if gap > from { gap - 1 } else { gap })
}

/// How tall each prompt's row in the queue is, one line whatever it holds.
const QUEUED_ROW_HEIGHT: Pixels = px(28.);

/// How many of a queued prompt's lines its tooltip gives.
const QUEUED_TOOLTIP_LINES: usize = 6;

/// A queued prompt's tooltip: its first few lines, as typed, and an
/// ellipsis where it goes on.
fn queued_tooltip(text: &str) -> SharedString {
    let text = text.trim_matches('\n');
    let mut lines: Vec<&str> = text.lines().take(QUEUED_TOOLTIP_LINES + 1).collect();
    if lines.len() > QUEUED_TOOLTIP_LINES {
        lines.truncate(QUEUED_TOOLTIP_LINES);
        lines.push("…");
    }
    lines.join("\n").into()
}

/// How near an edge of a scrolling area an item dragged over it scrolls it.
const DRAG_SCROLL_EDGE: Pixels = px(32.);

/// How far along a tab bar a "row" is, for how fast a drag scrolls it.
const DRAG_SCROLL_TAB: Pixels = px(120.);

/// The fastest a drag scrolls an area: about a row every 50 milliseconds.
const DRAG_SCROLL_ROW_TIME: Duration = Duration::from_millis(50);

/// How fast, in pixels a second, an item dragged with the pointer at `at`,
/// along an area running from `start` to `end`, scrolls it: towards the end
/// when positive, the start when negative, and not at all away from both
/// edges. Slow at first, faster the nearer the pointer is to the edge, or
/// the further past it, up to a `row` every [`DRAG_SCROLL_ROW_TIME`].
fn drag_scroll_speed(at: Pixels, start: Pixels, end: Pixels, row: Pixels) -> f32 {
    let fastest = row.as_f32() / DRAG_SCROLL_ROW_TIME.as_secs_f32();
    let edge = DRAG_SCROLL_EDGE.as_f32();
    // How far into the edge's band it is, a band's width past it fastest.
    let speed = |into: f32| fastest * (into / (2. * edge)).clamp(0.1, 1.);
    let (from_start, to_end) = ((at - start).as_f32(), (end - at).as_f32());
    if from_start < edge && from_start <= to_end {
        -speed(edge - from_start)
    } else if to_end < edge {
        speed(edge - to_end)
    } else {
        0.
    }
}

/// Scrolls an area of drag-reorderable items while one is dragged near its
/// edge, as the DragReorderBehaviour says, and has the gap shown chosen
/// anew every frame from where the pointer is over the items now there,
/// however the area scrolled, by the drag or the wheel.
#[derive(Clone, Default)]
struct DragScroll(Rc<Cell<Option<DragScrolling>>>);

#[derive(Clone, Copy)]
struct DragScrolling {
    /// Where the pointer is.
    at: Point<Pixels>,
    /// When the area was last scrolled, while it goes on scrolling.
    scrolled: Option<Instant>,
}

impl DragScroll {
    /// The pointer is at `at`, an item being dragged.
    fn follow(&self, at: Point<Pixels>) {
        let scrolled = self.0.get().and_then(|state| state.scrolled);
        self.0.set(Some(DragScrolling { at, scrolled }));
    }

    /// An element, taking no room, that every frame of a drag scrolls the
    /// area `handle` tracks once the pointer is near its edge, along it
    /// `vertical`ly or not, by `row`s, and then calls `choose` with where the
    /// pointer is, the area's bounds, and each item's bounds as now laid out,
    /// which says whether the gap shown changed, `view` drawn again if so.
    fn driver(
        &self,
        handle: &ScrollHandle,
        vertical: bool,
        row: Pixels,
        view: EntityId,
        choose: impl Fn(Point<Pixels>, Bounds<Pixels>, &dyn Fn(usize) -> Option<Bounds<Pixels>>) -> bool
            + 'static,
    ) -> impl IntoElement {
        let (state, handle) = (self.0.clone(), handle.clone());
        canvas(
            move |_, window, cx| {
                let Some(DragScrolling { at, scrolled }) = state.get() else {
                    return;
                };
                if !cx.has_active_drag() {
                    state.set(None);
                    return;
                }
                let area = handle.bounds();
                let max = handle.max_offset();
                let (along, start, end, max) = if vertical {
                    (at.y, area.top(), area.bottom(), max.y)
                } else {
                    (at.x, area.left(), area.right(), max.x)
                };
                // An area holding every item in view doesn't scroll.
                let speed = if max > px(0.) {
                    drag_scroll_speed(along, start, end, row)
                } else {
                    0.
                };
                let mut now_scrolled = None;
                if speed != 0. {
                    let now = Instant::now();
                    let since = scrolled.map_or(Duration::from_millis(16), |then| {
                        now.saturating_duration_since(then).min(Duration::from_millis(100))
                    });
                    let mut offset = handle.offset();
                    let current = if vertical { &mut offset.y } else { &mut offset.x };
                    // Scrolled further on, the offset is further below zero.
                    let next = (*current - px(speed * since.as_secs_f32()))
                        .max(-max)
                        .min(px(0.));
                    if next != *current {
                        *current = next;
                        handle.set_offset(offset);
                        now_scrolled = Some(now);
                        // Smoothly, frame by frame, until its end.
                        window.on_next_frame(move |_, cx| cx.notify(view));
                    }
                }
                state.set(Some(DragScrolling {
                    at,
                    scrolled: now_scrolled,
                }));
                let offset = handle.offset();
                let item = |ix: usize| {
                    handle.bounds_for_item(ix).map(|bounds| Bounds {
                        origin: bounds.origin + offset,
                        size: bounds.size,
                    })
                };
                if choose(at, area, &item) && now_scrolled.is_none() {
                    window.on_next_frame(move |_, cx| cx.notify(view));
                }
            },
            |_, _, _, _| {},
        )
        .absolute()
        .size_0()
    }
}

/// The insertion indicator of a drag reorder: a 2 pixel accent line across
/// the gap, drawn over the items, with a small open circle at its leading
/// end, taking no mouse. `vertical` for a line between tabs side by side;
/// `after` for one along the item's far edge rather than its near one.
fn drop_indicator(vertical: bool, after: bool, cx: &App) -> AnyElement {
    let accent = cx.theme().accent;
    let (line, dot) = (px(2.), px(6.));
    let circle = div()
        .absolute()
        .size(dot)
        .rounded_full()
        .border_2()
        .border_color(accent)
        .bg(cx.theme().background);
    let bar = div().absolute().bg(accent).rounded_full();
    let edge = -line / 2.;
    if vertical {
        div()
            .absolute()
            .top_0()
            .bottom_0()
            .w(line)
            .map(|this| {
                if after {
                    this.right(edge)
                } else {
                    this.left(edge)
                }
            })
            .child(bar.top(dot).bottom_0().left_0().right_0())
            .child(circle.top_0().left(-(dot - line) / 2.))
            .into_any_element()
    } else {
        div()
            .absolute()
            .left_0()
            .right_0()
            .h(line)
            .map(|this| {
                if after {
                    this.bottom(edge)
                } else {
                    this.top(edge)
                }
            })
            .child(bar.left(dot).right_0().top_0().bottom_0())
            .child(circle.left_0().top(-(dot - line) / 2.))
            .into_any_element()
    }
}

/// A file tab's close button: a square this big, drawn this far into the
