            recalled: None,
            working: Lanes::NONE,
            history_stale: false,
            _history_load: Task::ready(()),
            task_history: HistoryList::tasks(),
            queue: Vec::new(),
            next_queue_id: 0,
            queue_expanded: false,
            auto_send: true,
            queue_held: false,
            files: Vec::new(),
            selected_file: None,
            latest_settled: None,
            selected_task: None,
            next_chain_stamp: None,
            parked_outputs: HashMap::new(),
            mode_tab: SendMode::Both,
            disk_conflicts: Vec::new(),
