    /// The file in the selected tab, if a file's tab is selected.
    pub fn open_file_view(&self) -> Option<Entity<FileView>> {
        self.selected_file
            .and_then(|ix| self.files.get(ix))
            .map(|tab| tab.view.clone())
    }

