    async fn tasks_are_named_after_their_titles(cx: &mut TestAppContext) {
        use crate::chat_input::SendMode;
        fn titled(_: &std::path::Path, prompt: &str) -> anyhow::Result<String> {
            assert_eq!(prompt, "Tidy the queue up");
