        .unwrap();

        prompt_mode.update(cx, |this, cx| {
            this.ask_session = Some(Session {
                project_dir: dir.clone(),
                in_container: None,
                id: "questions".into(),
                context: Some(1200),
                system_prompt: None,
            });
            this.new_conversation(cx);
