            queue_gap: Rc::default(),
            tab_gap: Rc::default(),
            queue_drag_scroll: DragScroll::default(),
            tabs_drag_scroll: DragScroll::default(),
            scroll_push: Rc::default(),
            output_locked: false,
            output_left: None,
            queue_scroll: ScrollHandle::new(),
            chat_input,
            editing_queued: None,
            queue_expanded_by_up: false,
            recalled: None,
            working: Lanes::NONE,
            history_stale: false,
            _history_load: Task::ready(()),
            task_history: HistoryList::tasks(),
            queue: Vec::new(),
            next_queue_id: 0,
            queue_expanded: false,
            auto_send: true,
            queue_held: false,
            files: Vec::new(),
            selected_file: None,
            latest_settled: None,
            selected_task: None,
            next_chain_stamp: None,
            parked_outputs: HashMap::new(),
            mode_tab: SendMode::Both,
            disk_conflicts: Vec::new(),
            conflict_asked: None,
            tabs_scroll: ScrollHandle::new(),
            refs_shown: false,
            refs_opened: None,
            refs_closing: None,
            scroll_slide: None,
            slide_height: Rc::default(),
            refs_width: Rc::new(Cell::new(referenced_spec::WIDTH)),
            refs_panels: referenced_spec::PanelHeights::default(),
            _elapsed_tick: Task::ready(()),
