            let rows = this.ask_pane.rows();
            assert!(rows.count() > 200 * 4, "{} rows", rows.count());
            let drawn = (0..rows.count())
                .filter(|ix| rows.state().bounds_for_item(*ix).is_some())
                .count();
            assert!(drawn < 200, "{drawn} rows were laid out");
        });
    }

