        run_until(cx, &prompt_mode, "the resend's naming", |this| {
            this.tasks
                .get(1)
                .is_some_and(|task| task.name.as_ref() == "TidyTheQueue2")
        });
        prompt_mode.update(cx, |this, cx| this.cancel_task(1, cx));
        run_until(cx, &prompt_mode, "the resend's cancel", |this| {
            !this.working.any()
        });
