            TaskStatus::Unrecorded,
        ] {
            let ix = prompt_mode.update(cx, |this, cx| {
                let ix = this.push_task("Fix it".into(), cx);
                this.tasks[ix].status = status;
                this.tasks[ix].cancel = Some(super::Cancel {
                    cancelled: Default::default(),
