    /// The usage's summary, muted like the context figure unless a plan
    /// limit is nearly or wholly used, with its popover above it.
    /// The model picker, as the ChatInputScope's model says: the model the
    /// next prompt goes to, which opens a menu above it of those the harness
    /// in use can be told, Default first; disabled on Freeform, which goes
    /// to the default.
    fn render_model_picker(&self, cx: &mut Context<Self>) -> AnyElement {
        use gpui_kit::component::menu::{DropdownMenu as _, PopupMenuItem};
        let agent = crate::agent::current();
        let freeform = self.mode() == SendMode::Freeform;
        let chosen = crate::models::chosen(agent).filter(|_| !freeform);
        let label = crate::models::label(agent, chosen.as_deref());
        let tooltip = if freeform {
            "Freeform prompts are passed to the harness as typed, and go to its default model"
                .to_string()
        } else {
            match &chosen {
                Some(_) => format!("The next prompts sent go to {label}"),
                None => "The next prompts sent go to the harness's default model".to_string(),
            }
        };
        let muted = cx.theme().muted_foreground;
        let button = Button::new("model-picker")
            .ghost()
            .xsmall()
            .label(label)
            .dropdown_caret(true)
            .text_color(muted)
            .disabled(freeform)
            .tooltip(tooltip);
        if freeform {
            return button.into_any_element();
        }
        let this = cx.entity().downgrade();
        button
            .dropdown_menu_with_anchor(gpui_kit::Anchor::BottomLeft, move |menu, _, cx| {
                let chosen = crate::models::chosen(agent);
                let muted = cx.theme().muted_foreground;
                let entries = std::iter::once((None, "Default".to_string(), "The harness's own".to_string()))
                    .chain(
                        crate::models::available(agent)
                            .into_iter()
                            .map(|model| (Some(model.id), model.label, model.full)),
                    );
                let mut menu = menu.min_w(px(220.));
                for (id, label, full) in entries {
                    let this = this.clone();
                    let picked = id.clone();
                    let item = PopupMenuItem::element(move |_, _| {
                        h_flex()
                            .gap_2()
                            .child(label.clone())
                            .child(div().text_xs().text_color(muted).child(full.clone()))
                    })
                    .checked(chosen == id)
                    .on_click(move |_, _, cx| {
                        crate::models::choose(agent, picked.clone());
                        this.update(cx, |_, cx| cx.notify()).ok();
                    });
                    menu = menu.item(item);
                }
                menu
            })
            .into_any_element()
    }

    fn render_usage(&self, viewport: Size<Pixels>, cx: &mut Context<Self>) -> AnyElement {
        let (text, level) = self.usage.summary();
        let color = level.color(cx).unwrap_or(cx.theme().muted_foreground);
        let hover = cx.theme().foreground;
        let bounds = self.usage_bounds.clone();
        let summary = div()
            .id("chat-usage")
            .relative()
            .flex_none()
            .whitespace_nowrap()
            .text_xs()
            .text_color(color)
            .cursor_pointer()
            .hover(move |this| this.text_color(hover))
            .child(text)
            .child(
                canvas(move |laid_out, _, _| bounds.set(laid_out), |_, _, _, _| {})
                    .absolute()
                    .top_0()
                    .left_0()
                    .size_full(),
            )
            .when(!self.usage_open, |this| {
                this.tooltip(|window, cx| {
                    Tooltip::new("Click for the agent's usage in detail").build(window, cx)
                })
            })
            .on_click(cx.listener(|this, _, window, cx| this.toggle_usage(window, cx)));
        div()
            .relative()
            .flex_none()
            .child(gpui_kit::TestSupportExt::test_support(summary))
            .children(self.render_usage_popover(viewport, cx))
            .into_any_element()
    }

    /// The usage's popover, above its summary, its right edge on the
    /// summary's: its two columns side by side where the window, `viewport`
    /// big, has room for them, never wider than the window less a margin each
    /// side, and scrolling as a whole when taller than the room above the
    /// summary.
    fn render_usage_popover(
        &self,
        viewport: Size<Pixels>,
        cx: &mut Context<Self>,
    ) -> Option<AnyElement> {
        if !self.usage_open {
            return None;
        }
        let theme = cx.theme();
        let summary = self.usage_bounds.clone();
        let widest = viewport.width - USAGE_POPOVER_MARGIN * 2.;
        let side_by_side = widest
            >= usage::COLUMN_WIDTH * 2. + usage::COLUMN_GAP + USAGE_POPOVER_PADDING * 2. + px(2.);
        // The room above the summary, less the gap beneath the popover and
        // the margin above it.
        let room = summary.get().top() - px(4.) - USAGE_POPOVER_MARGIN;
        let popover = div()
            .id("usage-popover")
            .absolute()
            .bottom_full()
            .right_0()
            .mb_1()
            .p(USAGE_POPOVER_PADDING)
            .max_w(widest)
            .when(room > px(0.), |this| this.max_h(room))
            .overflow_y_scroll()
            .bg(theme.popover)
            .text_color(theme.popover_foreground)
            .border_1()
            .border_color(theme.border)
            .rounded(theme.radius)
            .shadow_md()
            .occlude()
            .on_mouse_down_out(cx.listener(move |this, event: &MouseDownEvent, _, cx| {
                // Pressing the summary closes it by toggling.
                if !summary.get().contains(&event.position) {
                    this.usage_open = false;
                    cx.notify();
                }
            }))
            .child(usage::details(&self.usage, usage::now(), side_by_side, cx));
        // Lets UI tests find the popover; inert in normal builds.
        Some(
            deferred(gpui_kit::TestSupportExt::test_support(popover))
                .with_priority(1)
                .into_any_element(),
        )
    }

