            piton_syntax::init();
            ProjectDirectory::init(cx);
            ProjectDirectory::set(PathBuf::from(env!("CARGO_MANIFEST_DIR")), cx);
            crate::project_lsp::ProjectLsp::init(cx);
        });

        let mut chat_input = None;
        let window = cx.add_window(|window, cx| {
