const MAX_ROWS: usize = 12;

#[cfg(target_os = "macos")]
const SEND_SHORTCUT: &str = "⌘Enter";
#[cfg(not(target_os = "macos"))]
const SEND_SHORTCUT: &str = "Ctrl+Enter";

