        })
        .unwrap();
        cx.run_until_parked();
        assert!(find(("notice-details", notice_row), cx), "it didn't open");
        cx.update_window(handle, |_, window, cx| {
            window.click(("notice-summary", notice_row), cx)
        })
        .unwrap();
        cx.run_until_parked();
        assert!(!find(("notice-details", notice_row), cx), "it didn't close");
